def isok(x: int) -> bool:
    x = str(x)
    for i in range(len(x) // 2):
        if x[i] != x[-i - 1]:
            return False
    return True

def find_max_palindromic_cube(n: int) -> int:
    ans = 0
    i = 1
    while i**3 <= n:
        if isok(i**3):
            ans = i**3
        i += 1
    return ans

n = int(input())
print(find_max_palindromic_cube(n))
